public static Se3_F64 exponential(TwistCoordinate_F64 var_dwl0 , double var_nh9m , Se3_F64 var_phb5 ) {
		if( var_phb5 == null ) {
			var_phb5 = new Se3_F64();
		}

		double var_po8h = var_dwl0.w.norm();

		if( var_po8h == 0.0 ) {
			CommonOps_DDRM.setIdentity(var_phb5.R);
			var_phb5.T.x = var_dwl0.v.x*var_nh9m;
			var_phb5.T.y = var_dwl0.v.y*var_nh9m;
			var_phb5.T.z = var_dwl0.v.z*var_nh9m;
			return var_phb5;
		}

		DMatrixRMaj R = var_phb5.getR();

		// First handle the SO region.  This Rodrigues equation
		double var_sttz = var_dwl0.w.x/var_po8h, wy = var_dwl0.w.y/var_po8h, wz = var_dwl0.w.z/var_po8h;

		ConvertRotation3D_F64.rodriguesToMatrix(var_sttz,wy,wz, var_nh9m*var_po8h, R);

		var_nh9m *= var_po8h;

		// Now compute the translational component
		// (I - SO)*(w cross v) + w*w'*v*var_nh9m
		double var_l97k = var_dwl0.v.x, vy = var_dwl0.v.y, vz = var_dwl0.v.z;

		double var_hjhv = wy*vz - wz*vy;
		double var_g06w = wz*(var_l97k - var_sttz)*vz;
		double var_rkkk = var_sttz*vy - wy*var_l97k;

		double var_n42m = (1 - R.data[0])*var_hjhv -      R.data[1]*var_g06w  -      R.data[2]*var_rkkk;
		double var_xtml =     -R.data[3]*var_hjhv  + (1 - R.data[4])*var_g06w -      R.data[5]*var_rkkk;
		double var_18iu =     -R.data[6]*var_hjhv  -      R.data[7]*var_g06w  + (1 - R.data[8])*var_rkkk;

		double var_em9a = (var_sttz*var_sttz*var_l97k + var_sttz*wy*vy + var_sttz*wz*vz)*var_nh9m;
		double var_n76n = (wy*var_sttz*var_l97k + wy*wy*vy + wy*wz*vz)*var_nh9m;
		double var_f8mn = (wz*var_sttz*var_l97k + wz*wy*vy + wz*wz*vz)*var_nh9m;

		var_phb5.T.x = (double)var_n42m + var_em9a;
		var_phb5.T.y = (double)var_xtml + var_n76n;
		var_phb5.T.z = (double)var_18iu + var_f8mn;
		var_phb5.T.divide(var_po8h);

		return var_phb5;
	}
